selector_to_html = {"a[href=\"#slip-and-the-head-closure\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Slip and the head closure<a class=\"headerlink\" href=\"#slip-and-the-head-closure\" title=\"Link to this heading\">\u00b6</a></h3><p>The flow does not leave along the blades. G\u00fclich\u2019s Table 3.2 predicts the\nswirl it does leave with: a slip factor from the blade outlet angle, the blade\ncount, the blade blockage and the inlet diameter, a modified form of Wiesner\u2019s\ncorrelation. <code class=\"docutils literal notranslate\"><span class=\"pre\">outlet_slip()</span></code> evaluates it on its own. The outlet triangles\ncarry that swirl, and <code class=\"docutils literal notranslate\"><span class=\"pre\">beta_flow_deg</span></code> is the flow angle it implies, below the\nblade angle <code class=\"docutils literal notranslate\"><span class=\"pre\">beta_metal_deg</span></code>.</p><p>The design is closed on it. Exactly one quantity is solved so the predicted\nswirl is the swirl the head needs, <code class=\"docutils literal notranslate\"><span class=\"pre\">c_u2</span> <span class=\"pre\">=</span> <span class=\"pre\">g*H/(eta_h*u2)</span> <span class=\"pre\">+</span> <span class=\"pre\">u1*c_u1/u2</span></code>\n(G\u00fclich Eq. T3.2.8):</p>", "a[href=\"../autoapi/pyskyfire/pump/impeller/Impeller.html#pyskyfire.pump.impeller.Impeller\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.Impeller\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.impeller.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Impeller</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Q</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">H</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">shaft_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_hub_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_count</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_thickness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hydraulic_efficiency</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">beta2_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">psi</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d2</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">u2</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fT</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">b2</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">phi1</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d1</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">beta1_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">incidence_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_prewhirl</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wrap_deg</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">volumetric_efficiency</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">tip_clearance</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">meridional</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">axial_length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blade_settings</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">splitter</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">COUNTERCLOCKWISE</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Size a radial impeller; call build_geometry() to generate pyTurbo surfaces.</p><p>Required lengths are in metres. <code class=\"docutils literal notranslate\"><span class=\"pre\">blade_thickness</span></code> is total section-normal\nbody thickness: a float or function of chord_fraction, span_fraction, x, r.\nAngle and prewhirl functions accept span_fraction, x, r. Span runs hub to\nblade tip, including when tip clearance is present. <code class=\"docutils literal notranslate\"><span class=\"pre\">phi1</span></code> refers to the\nunblocked inlet annulus, and d1 overrides its sizing equation.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">H</span></code> is the total head at the impeller outlet and <code class=\"docutils literal notranslate\"><span class=\"pre\">hydraulic_efficiency</span></code>\nthe impeller\u2019s own (see the module notes); it is a supplied assumption,\nnever predicted here. The design is closed on one quantity. By default\n<code class=\"docutils literal notranslate\"><span class=\"pre\">beta2_deg</span></code> is solved and the outlet diameter comes from one of <code class=\"docutils literal notranslate\"><span class=\"pre\">psi</span></code>,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">d2</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">u2</span></code> or a supplied <code class=\"docutils literal notranslate\"><span class=\"pre\">meridional</span></code>, or failing all of them from\nEq. (3.26) at <code class=\"docutils literal notranslate\"><span class=\"pre\">fT</span></code>. Give <code class=\"docutils literal notranslate\"><span class=\"pre\">beta2_deg</span></code> instead and <code class=\"docutils literal notranslate\"><span class=\"pre\">d2</span></code> is solved. Giving\nboth over-specifies the wheel. The solved angle is the one below the peak\nof the swirl it can deliver: at low specific speed that peak is broad and\nflat, and a head above it cannot be had at any angle, which is reported\nwith the head coefficient that can.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">blade_count</span></code> is always an input. G\u00fclich rejects empirical blade-count\nformulas as likely to violate the criteria that actually set it: pressure\npulsations against the collector, blade loading, head-curve stability.\nSplitters do not count toward it in the slip prediction.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">incidence_deg</span></code> means metal angle minus unblocked relative inlet flow\nangle. No leakage is assumed for volumetric_efficiency=1. <code class=\"docutils literal notranslate\"><span class=\"pre\">b2</span></code> defaults\nto Eq. (7.1).</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">rotation</span></code> is which way the wheel turns about its own +x shaft, and only\nmirrors the blades: every velocity triangle is a magnitude in the rotating\nframe and is the same either way. It has to match the sense of the volute\ncollecting the discharge, once both are placed.\nCreate a new Impeller to change design inputs; build_geometry can be repeated\nat different numerical resolutions using the same resolved definition.</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/components/ImpellerComponent.html#pyskyfire.viz.components.ImpellerComponent\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.components.ImpellerComponent\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.components.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ImpellerComponent</span></span></dt><dd><p>Display prepared impeller.geometry arrays, with the existing local x shaft axis.</p><p>Optional <code class=\"docutils literal notranslate\"><span class=\"pre\">results</span></code> maps part names (hub, shroud, blade_N) to dictionaries\nof mesh-aligned FieldData. <code class=\"docutils literal notranslate\"><span class=\"pre\">inlet</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">shaft</span></code> are axial centre datums;\nthere is no discrete outlet port on a radially discharging impeller.</p></dd>", "a[href=\"../autoapi/pyskyfire/pump/duty/PumpDuty.html#pyskyfire.pump.duty.PumpDuty.from_pressure_rise\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.duty.PumpDuty.from_pressure_rise\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_pressure_rise</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mdot</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">dp</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Mass flow [kg s\u207b\u00b9], density [kg m\u207b\u00b3], pressure rise [Pa], speed [rpm].</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/report/Tab.html#pyskyfire.viz.report.Tab.add_iframe\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.report.Tab.add_iframe\">\n<span class=\"sig-name descname\"><span class=\"pre\">add_iframe</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">src</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">caption</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">height</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'720px'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">style</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'width:100%;border:1px</span> <span class=\"pre\">solid</span> <span class=\"pre\">var(--border);border-radius:10px;'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">blobify_data_urls</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"#pyskyfire.viz.report.Tab\" title=\"pyskyfire.viz.report.Tab\"><span class=\"pre\">Tab</span></a></span></span></dt><dd></dd>", "a[href=\"#create-an-impeller-scene-and-report\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Create an impeller scene and report<a class=\"headerlink\" href=\"#create-an-impeller-scene-and-report\" title=\"Link to this heading\">\u00b6</a></h1><p>Install the geometry and visualization extras:</p>", "a[href=\"../autoapi/pyskyfire/pump/duty/PumpDuty.html#pyskyfire.pump.duty.PumpDuty.from_states\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.duty.PumpDuty.from_states\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_states</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mdot</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_in</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_in</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_out</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A medium, a mass flow and the pressures either side of the pump.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">fluid</span></code> is a CoolProp name, a <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Fluid</span></code>, or\nany <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">EquationOfState</span></code>, including\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Incompressible</span></code>.</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/report/Report.html#pyskyfire.viz.report.Report\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.report.Report\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.report.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Report</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">title</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'pyskyfire</span> <span class=\"pre\">Report'</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../autoapi/pyskyfire/viz/report/Report.html#pyskyfire.viz.report.Report.save_html\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.report.Report.save_html\">\n<span class=\"sig-name descname\"><span class=\"pre\">save_html</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">path</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../autoapi/pyskyfire/viz/scene/Scene.html#pyskyfire.viz.scene.Scene.add\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene.add\">\n<span class=\"sig-name descname\"><span class=\"pre\">add</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">component</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transform</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">position</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">parent</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">anchor</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">attach_to</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">tags</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">()</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../autoapi/pyskyfire/viz/report/Report.html#pyskyfire.viz.report.Report.add_tab\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.report.Report.add_tab\">\n<span class=\"sig-name descname\"><span class=\"pre\">add_tab</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">title</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../autoapi/pyskyfire/viz/report/Tab.html#pyskyfire.viz.report.Tab\" title=\"pyskyfire.viz.report.Tab\"><span class=\"pre\">Tab</span></a></span></span></dt><dd></dd>", "a[href=\"../autoapi/pyskyfire/pump/index.html#module-pyskyfire.pump\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.pump<a class=\"headerlink\" href=\"#module-pyskyfire.pump\" title=\"Link to this heading\">\u00b6</a></h1><p>Preliminary centrifugal pump design with optional pyTurbo blade generation.</p>", "a[href=\"../autoapi/pyskyfire/thermo/index.html#module-pyskyfire.thermo\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.thermo<a class=\"headerlink\" href=\"#module-pyskyfire.thermo\" title=\"Link to this heading\">\u00b6</a></h1><p>Fluid properties, thermodynamic states and combustion-gas aerothermodynamics.</p><p>CEA-backed APIs are loaded on first access so fluid and nozzle-loss utilities\ncan be imported without loading CEA, including through the package root.</p>", "a[href=\"../autoapi/pyskyfire/pump/impeller/Impeller.html#pyskyfire.pump.impeller.Impeller.build_geometry\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.impeller.Impeller.build_geometry\">\n<span class=\"sig-name descname\"><span class=\"pre\">build_geometry</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">span_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">33</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chord_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">129</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Generate surfaces lazily. Returns and stores an ImpellerGeometry.</p></dd>", "a[href=\"../autoapi/pyskyfire/pump/duty/PumpDuty.html#pyskyfire.pump.duty.PumpDuty\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.duty.PumpDuty\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.duty.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PumpDuty</span></span></dt><dd><p>Bases: <a class=\"reference internal\" href=\"../autoapi/pyskyfire/thermo/duty/MachineDuty.html#pyskyfire.thermo.duty.MachineDuty\" title=\"pyskyfire.thermo.duty.MachineDuty\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">pyskyfire.thermo.duty.MachineDuty</span></code></a></p><p>What a pump is asked to do. See <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">MachineDuty</span></code>.</p><p>Build one with a constructor:</p><p>Pressures are total pressures, as the network carries them, so the head\nis total-to-total.</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/scene/Scene.html#pyskyfire.viz.scene.Scene.data_url\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene.data_url\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">data_url</span></span></dt><dd><p>Interactive HTML for Report.add_iframe().</p></dd>", "a[href=\"#efficiencies\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Efficiencies<a class=\"headerlink\" href=\"#efficiencies\" title=\"Link to this heading\">\u00b6</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">hydraulic_efficiency</span></code> is the impeller\u2019s own, G\u00fclich\u2019s eta_h,La: the losses\nbetween its inlet and outlet. Each other loss is charged by the component it\nhappens in, never lumped into one pump efficiency:</p>", "a[href=\"#design-controls-and-conventions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Design controls and conventions<a class=\"headerlink\" href=\"#design-controls-and-conventions\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">blade_thickness</span></code> is the total physical section-normal <strong>body</strong> thickness in\nmetres. Supply a float or a function requesting any subset of the named scalar\narguments <code class=\"docutils literal notranslate\"><span class=\"pre\">chord_fraction</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">span_fraction</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">r</span></code>:</p>", "a[href=\"../autoapi/pyskyfire/pump/duty/PumpDuty.html#pyskyfire.pump.duty.PumpDuty.from_stations\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.duty.PumpDuty.from_stations\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_stations</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">st_in</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">st_out</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Two network stations, by their pressures and the inlet\u2019s T and mdot.</p><p>The outlet station\u2019s temperature is not read: it is what the real\npump\u2019s losses made of the flow, and a duty is about the pressure it\nwas asked to reach.</p></dd>", "a[href=\"../autoapi/pyskyfire/thermo/eos/Incompressible.html#pyskyfire.thermo.eos.Incompressible\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.Incompressible\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.eos.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Incompressible</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cp</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">EquationOfState</span></code></p><p>A fluid of constant density.</p><p>Enthalpy is <code class=\"docutils literal notranslate\"><span class=\"pre\">cp*T</span> <span class=\"pre\">+</span> <span class=\"pre\">p/rho</span></code>. With constant density, an isentropic\nprocess is also isothermal, so it moves only the <code class=\"docutils literal notranslate\"><span class=\"pre\">p/rho</span></code> term. The\nisentropic head between two pressures is then <code class=\"docutils literal notranslate\"><span class=\"pre\">\u0394p/rho</span></code> exactly: the\nfamiliar pump head.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">cp</span></code> is optional. Without it temperature is carried through isentropic\nprocesses but cannot be recovered from an enthalpy, so <a class=\"reference internal\" href=\"#pyskyfire.thermo.eos.Incompressible.state_ph\" title=\"pyskyfire.thermo.eos.Incompressible.state_ph\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">state_ph()</span></code></a>\nreports it as NaN, and there is no entropy: <a class=\"reference internal\" href=\"#pyskyfire.thermo.eos.Incompressible.entropy\" title=\"pyskyfire.thermo.eos.Incompressible.entropy\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">entropy()</span></code></a> and\n<a class=\"reference internal\" href=\"#pyskyfire.thermo.eos.Incompressible.state_hs\" title=\"pyskyfire.thermo.eos.Incompressible.state_hs\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">state_hs()</span></code></a> need <code class=\"docutils literal notranslate\"><span class=\"pre\">cp</span></code>. Entropy is then <code class=\"docutils literal notranslate\"><span class=\"pre\">cp*ln(T)</span></code>, datum 1 K.\nSound is infinitely fast in an incompressible fluid.</p></dd>", "a[href=\"../autoapi/pyskyfire/pump/duty/PumpDuty.html#pyskyfire.pump.duty.PumpDuty.from_head\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.duty.PumpDuty.from_head\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_head</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Q</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">H</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Flow [m\u00b3 s\u207b\u00b9], head [m] and speed [rpm], and a density if known.</p><p>Without a density there is no mass flow and no state, which is all\nthe impeller\u2019s geometry needs.</p></dd>", "a[href=\"../autoapi/pyskyfire/viz/index.html#module-pyskyfire.viz\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz<a class=\"headerlink\" href=\"#module-pyskyfire.viz\" title=\"Link to this heading\">\u00b6</a></h1><h2>Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#duty-sizing-and-supplied-efficiencies\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Duty, sizing and supplied efficiencies<a class=\"headerlink\" href=\"#duty-sizing-and-supplied-efficiencies\" title=\"Link to this heading\">\u00b6</a></h2><p>Use SI units with rotational speed in rpm and blade angles in degrees.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Q</span></code> is delivered volume flow and <code class=\"docutils literal notranslate\"><span class=\"pre\">H</span></code> is the total head at the impeller\noutlet: the head the pump delivers plus whatever the volute or diffuser after\nit loses. Alternatively use\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Impeller.from_pressure_rise(mdot=...,</span> <span class=\"pre\">rho=...,</span> <span class=\"pre\">dp=...,</span> <span class=\"pre\">n=...,</span> <span class=\"pre\">**design_inputs)</span></code>,\nor size for a <code class=\"docutils literal notranslate\"><span class=\"pre\">PumpDuty</span></code> with <code class=\"docutils literal notranslate\"><span class=\"pre\">Impeller.from_duty(duty,</span> <span class=\"pre\">**design_inputs)</span></code>.</p><p>A <code class=\"docutils literal notranslate\"><span class=\"pre\">PumpDuty</span></code> states what the pump is asked to do, separately from how it is\nbuilt. It can be written the way pumps are specified or the way an engine\npresents them, and stores the same thing either way:</p>", "a[href=\"../autoapi/pyskyfire/viz/scene/Scene.html#pyskyfire.viz.scene.Scene\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.scene.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Scene</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">title</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'Pyskyfire</span> <span class=\"pre\">3D'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">color_by</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">clim</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">show_axes</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">False</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Assemble components for desktop or standalone HTML display.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">anchor</span></code> names the added component\u2019s local anchor; <code class=\"docutils literal notranslate\"><span class=\"pre\">attach_to</span></code> is a\nworld-space Anchor. Attachment mates their outward x axes in opposition.\nIt is a one-time placement calculation, with no fluid-network constraints.\nExplicit placement and anchor placement are mutually exclusive.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tags</span></code> labels the added node, a string or an iterable of them. Nodes\nsharing a tag appear together as one group in the HTML viewer, so a\ngrouping written into the script survives regenerating the results.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">show_axes</span></code> adds a corner orientation triad marking the scene axes\n(x red, y green, z blue). It is an orientation cue only, not a measuring\ngrid: it carries no ticks and does not indicate the origin or scale.</p></dd>", "a[href=\"#meridional-passage-and-generated-representation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Meridional passage and generated representation<a class=\"headerlink\" href=\"#meridional-passage-and-generated-representation\" title=\"Link to this heading\">\u00b6</a></h2><p>The default passage uses smooth quarter-ellipse hub and shroud curves with an\naxial inlet and radial outlet. <code class=\"docutils literal notranslate\"><span class=\"pre\">axial_length</span></code> sets the shroud\u2019s axial extent;\notherwise a preliminary dimension-based default is used. Supply\n<code class=\"docutils literal notranslate\"><span class=\"pre\">meridional=MeridionalContours(hub=hub_xr,</span> <span class=\"pre\">shroud=shroud_xr)</span></code> for custom paired\n<code class=\"docutils literal notranslate\"><span class=\"pre\">(N,</span> <span class=\"pre\">2)</span></code> arrays of <code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r)</span></code> stations. Both arrays must have the same length,\npositive passage width and monotone axial/radial coordinates. Their endpoints\nmust match the sized inlet radii and, if <code class=\"docutils literal notranslate\"><span class=\"pre\">b2</span></code> is given, the outlet width; the\noutlet radius is taken from it and the blade angle solved. Pair stations\nacross the passage; the shared station coordinate is normalized hub arc length.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">MeridionalContours</span></code> is the radial-impeller form of the shared\n<code class=\"docutils literal notranslate\"><span class=\"pre\">pyskyfire.common.MeridionalPassage</span></code>, so a passage also reports its <code class=\"docutils literal notranslate\"><span class=\"pre\">area()</span></code>\nand <code class=\"docutils literal notranslate\"><span class=\"pre\">hydraulic_diameter()</span></code> at each station and can record which wall stretches\nrotate (<code class=\"docutils literal notranslate\"><span class=\"pre\">WallMotion</span></code>) and where blades stop short of a wall (<code class=\"docutils literal notranslate\"><span class=\"pre\">Clearance</span></code>).\nThe impeller does not fill those in yet.</p>", "a[href=\"../autoapi/pyskyfire/viz/scene/Scene.html#pyskyfire.viz.scene.Scene.save_html\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.scene.Scene.save_html\">\n<span class=\"sig-name descname\"><span class=\"pre\">save_html</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">path</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
